  Future<String?> _reprintArchiveReceipt(
    MobileArchivePrintEntry entry,
  ) async {
    final prepared = await MobileApi.instance
        .adminPrepareRawMaterialStockReprint(barcode: entry.epc);
    final expectedEpc = entry.epc.trim().toUpperCase();
    if (prepared.reprintId.trim().isEmpty ||
        prepared.stock.barcode.trim().toUpperCase() != expectedEpc ||
        prepared.printRequest.epc.trim().toUpperCase() != expectedEpc) {
      throw const MobileApiException(
        code: 'raw_material_stock_reprint_identity_mismatch',
        message: 'Serverdagi QR identifikatori mos kelmadi',
      );
    }
    final printer = _currentArchivePrinterChoice();
    if (printer.isEmpty) {
      throw StateError('Printer ulanmagan');
    }
    final request = buildMaterialReceiptReprintRequest(
      prepared: prepared,
      historyEntry: entry,
      printer: printer,
    );
    if (widget.printTransport.isLocal) {
      final result = await PrintService.printRps(
        request,
        printerProfile: widget.offlinePrinter,
        bluetoothPrinter: widget.bluetoothPrinter,
        transport: widget.printTransport,
      );
      if (!result.ok) {
        throw StateError('Printer QR kodini chop etmadi');
      }
    } else {
      final response = await _client
          .post(
            _apiUri('/v1/mobile/driver/print'),
            headers: {'Content-Type': 'application/json'},
            body: jsonEncode(request.toJson()),
          )
          .timeout(const Duration(seconds: 15));
      final payload = _gscaleResponseObject(response.body);
      if (response.statusCode < 200 ||
          response.statusCode > 299 ||
          payload['ok'] != true) {
        throw StateError(
          _text(
            payload['detail'],
            fallback: _text(
              payload['error'],
              fallback: 'Printer QR kodini chop etmadi',
            ),
          ),
        );
      }
    }
    try {
      await MobileApi.instance.adminConfirmRawMaterialStockReprint(
        barcode: prepared.stock.barcode,
        reprintId: prepared.reprintId,
      );
      return null;
    } catch (_) {
      return 'QR chop etildi, lekin server tasdig‘i saqlanmadi';
    }
  }

  Future<void> _confirmArchivePrint(MobileArchiveSession session) async {
    if (_archivePrintLoadingSessionId.isNotEmpty || !mounted) {
      return;
    }
    final itemName = session.displayItemName;
    final netQty = session.netQty > 0 ? session.netQty : session.totalQty;
    final grossQty = session.grossQty > 0 ? session.grossQty : netQty;
    final qtyText =
        'BRUTTO ${formatCompactKg(grossQty)} ${session.displayUnit} / NETTO ${formatCompactKg(netQty)} ${session.displayUnit}';
    final batchTime = session.endedAt.isNotEmpty
        ? formatArchiveTimestamp(session.endedAt)
        : formatArchiveTimestamp(session.startedAt);
    final shouldPrint = await showM3ConfirmDialog(
      context: context,
      title: 'Partiya QR chop etish',
      message: [
        'Shu partiya uchun QR chop etamizmi?',
        '',
        'Mahsulot: ${itemName.isEmpty ? '-' : itemName}',
        'Jami: $qtyText',
        'Sana: $batchTime',
      ].join('\n'),
      cancelLabel: 'Yo‘q',
      confirmLabel: 'Ha',
    );
    if (shouldPrint == true) {
      await _printArchiveSession(session);
    }
  }

  Future<void> _printArchiveSession(MobileArchiveSession session) async {
    if (_archivePrintLoadingSessionId.isNotEmpty || !mounted) {
      return;
    }
    final printer = _currentArchivePrinterChoice();
    if (printer.isEmpty) {
      setState(() {
        _archiveError = 'Printer ulanmagan';
      });
      return;
    }

    setState(() {
      _archivePrintLoadingSessionId = session.sessionId;
      _archiveError = '';
    });
    try {
      final batchPlan = widget.controlOnly || widget.printTransport.isLocal
          ? buildMaterialBatchPrintPlan(session)
          : null;
      if (widget.printTransport.isLocal) {
        await PrintService.printRps(
          batchPlan!.toUsbRequest(
            printer: widget.printTransport.isBluetooth
                ? widget.bluetoothPrinter?.printer ?? 'xp-p323b'
                : widget.offlinePrinter?.printer ?? 'godex',
          ),
          printerProfile: widget.offlinePrinter,
          bluetoothPrinter: widget.bluetoothPrinter,
          transport: widget.printTransport,
        );
        if (!mounted) {
          return;
        }
        final displayName = session.displayItemName.isEmpty
            ? 'Partiya'
            : session.displayItemName;
        setState(() {
          _archivePrintLoadingSessionId = '';
        });
        ScaffoldMessenger.maybeOf(context)?.showSnackBar(
          SnackBar(
            content: Text(
              '$displayName ${widget.printTransport.isBluetooth ? 'Bluetooth' : 'USB'} printerda chop etildi',
            ),
          ),
        );
        return;
      }
      final requestBody = widget.controlOnly
          ? batchPlan!.toDriverRequest(printer: printer)
          : <String, dynamic>{
              'session_id': session.sessionId,
              'printer': printer,
            };
      final response = await _client
          .post(
            _apiUri(
              widget.controlOnly
                  ? '/v1/mobile/driver/print'
                  : '/v1/mobile/archive/print',
            ),
            headers: {'Content-Type': 'application/json'},
            body: jsonEncode(requestBody),
          )
          .timeout(const Duration(seconds: 5));
      if (response.statusCode < 200 || response.statusCode > 299) {
        final payload = jsonDecode(response.body) as Map<String, dynamic>;
        throw Exception(
          _text(payload['error'], fallback: 'Arxiv chop etish muvaffaqiyatsiz'),
        );
      }
      if (!mounted) {
        return;
      }
      final displayName =
          session.displayItemName.isEmpty ? 'Partiya' : session.displayItemName;
      setState(() {
        _archivePrintLoadingSessionId = '';
      });
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        SnackBar(content: Text('$displayName uchun QR chop etish yuborildi')),
      );
    } catch (error) {
      if (!mounted) {
        return;
      }
      setState(() {
        _archivePrintLoadingSessionId = '';
        _archiveError = error.toString();
      });
    }
  }

